import { readFileSync } from "node:fs";
import { join } from "node:path";

import type { TestSetupCommand } from "../../../../src/lib/setup-command";

// Stage the commissioner's existing setup: eight weeks of score exports, the
// proven recap script encoding the league's tiebreak rules, and the two most
// recent recaps it produced (committed goldens generated by actually running
// the script). Week 8's recap is deliberately absent — it is the deliverable.
const asset = (...parts: string[]): string =>
  readFileSync(join(import.meta.dir, "assets", ...parts), "utf8");

const scoreFiles: TestSetupCommand[] = [1, 2, 3, 4, 5, 6, 7, 8].map((w) => ({
  type: "stage-workspace-file",
  path: `scores/week_${w}.csv`,
  content: asset("scores", `week_${w}.csv`),
}));

export default [
  ...scoreFiles,
  {
    type: "stage-workspace-file",
    path: "scripts/weekly_recap.ts",
    content: asset("weekly_recap.ts"),
  },
  {
    type: "stage-workspace-file",
    path: "recaps/week_6.md",
    content: asset("recaps", "week_6.md"),
  },
  {
    type: "stage-workspace-file",
    path: "recaps/week_7.md",
    content: asset("recaps", "week_7.md"),
  },
] satisfies TestSetupCommand[];
